type PlatformType =
  | "macos"
  | "windows"
  | "linux"
  | "chromeos"
  | "web"
  | "ios"
  | "android";

  type signingMode = {
    "app-version" : string,
    "type" : PlatformType,
    "enabled" : boolean
  }


type folderType = "notification" | "payment" | "onboarding"

 interface baseConfigType {
  "api-global-version" : string,
  "api-base-local-version" : string
  "signing-mode" : signingMode[]
}



export type { baseConfigType,folderType };

